 async function submit(e){e.preventDefault();setBusy(true);setError('');if(form.github_url&&!parseGitHubRepository(form.github_url)){setError('Enter a valid GitHub repository URL, or leave it blank.');setBusy(false);return}try{if(onCreated){let emulatorId=createdId;if(!emulatorId){const d=await send('/entries','POST',{...form,recommended_game_ids:selectedGames.map(game=>game.id)});emulatorId=d.id;if(!emulatorId)throw new Error('The emulator was added but its ID was not returned. Please select it from the catalog.')}await onCreated(emulatorId,form.name)}else{const d=await send(id?'/entries/'+id:'/entries',id?'PUT':'POST',{...form,recommended_game_ids:selectedGames.map(game=>game.id)});nav('/emulators/'+(id||d.id))}}catch(e){if(e.existing)useExisting(e.existing);else setError(e.message||'The request failed. Please try again.')}finally{setBusy(false)}}
