function ModerationDialog({path,busy,error,onCancel,onConfirm}){const cancelRef=useRef(null),dialogRef=useRef(null);const denying=path.endsWith('/reject'),approving=path.endsWith('/approve'),deleting=path.endsWith('/delete');useEffect(()=>{const previous=document.activeElement;cancelRef.current?.focus();function keydown(e){if(e.key==='Escape'&&!busy){e.preventDefault();onCancel()}if(e.key==='Tab'){const buttons=[...dialogRef.current.querySelectorAll('button:not(:disabled)')];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}document.addEventListener('keydown',keydown);return()=>{document.removeEventListener('keydown',keydown);previous?.focus()}},[busy,onCancel]);return <div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onCancel()}}><div className="panel moderation-modal" role="dialog" aria-modal="true" aria-labelledby="moderation-title" aria-describedby="moderation-description" ref={dialogRef}><span className="section-label">MODERATION CONFIRMATION</span><h2 id="moderation-title">{approving?'APPROVE REPORT?':denying?'DENY REPORT?':deleting?'DELETE REPORT?':'CONFIRM ACTION?'}</h2><p id="moderation-description">{approving?'This report will be marked approved and removed from the review queue. It is already visible to everyone.':denying?'This report and its flags will be permanently deleted from the live database. This cannot be undone.':deleting?'This report and its flags will be deleted. This cannot be undone.':'Are you sure you want to perform this moderation action?'}</p>{error&&<div className="notice error" role="alert">{error}</div>}<div className="actions modal-actions"><button type="button" ref={cancelRef} className="btn dark" disabled={busy} onClick={onCancel}>Cancel</button><button type="button" className={'btn '+(denying||deleting?'red':'green')} disabled={busy} onClick={onConfirm}>{busy?'Working…':approving?'Approve report':denying?'Deny and delete':deleting?'Delete report':'Confirm'}</button></div></div></div>}
function HistoryItem({item}){const description=describeHistory(item);const date=new Date(item.created_at);const time=Number.isNaN(date.getTime())?String(item.created_at||''):date.toLocaleString();return <><span className="section-label">{item.admin_name} · {time}</span><strong>{description.title}</strong>{description.context&&<p>{description.context}</p>}</>}
function FlagReviewDialog({flag,onClose,onDone}){const [decision,setDecision]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const dialogRef=useRef(null);useEffect(()=>{const previous=document.activeElement;dialogRef.current?.focus();function keydown(e){if(e.key==='Escape'&&!busy){e.preventDefault();if(decision)setDecision(null);else onClose()}if(e.key==='Tab'){const buttons=[...dialogRef.current.querySelectorAll('button:not(:disabled)')];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}document.addEventListener('keydown',keydown);return()=>{document.removeEventListener('keydown',keydown);previous?.focus()}},[busy,decision]);async function confirm(){setBusy(true);setError('');try{await send('/admin/flag/'+flag.id+'/'+decision,'POST',{});onDone()}catch(e){setError(e.message||'Could not review this flag. Please try again.')}finally{setBusy(false)}}return <div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose()}}><div className="panel moderation-modal flag-review-modal" role="dialog" aria-modal="true" aria-labelledby="flag-review-title" tabIndex={-1} ref={dialogRef}><div className="flag-review-top"><div><span className="section-label">FLAG REVIEW</span><h2 id="flag-review-title">{flag.game_name} · {flag.emulator_name}</h2></div><button type="button" className="btn dark" disabled={busy} onClick={onClose} aria-label="Close flag review">Close</button></div><div className="flag-reason"><strong>FLAG REASON</strong><p>{flag.reason}</p><small>Flagged by {flag.reporter}</small></div><p className="flag-review-intro">Review the flag reason and the testing details below, then choose whether the compatibility report should stay on the site.</p><h3>COMPATIBILITY REPORT</h3><div className="flag-details">{[['Game',flag.game_name],['Emulator',flag.emulator_name],['Tester',flag.tester],['Revision',flag.revision],['Operating system',flag.os],['CPU',flag.cpu],['GPU',flag.gpu],['Result',flag.result],['Tested',String(flag.tested_at||'').slice(0,10)],['Game version',flag.game_version],['FPS',flag.fps],['Graphical issues',flag.graphics],['Emulator settings',flag.settings],['Testing notes',flag.notes]].map(([label,value])=><div key={label}><strong>{label}</strong><span>{value||'Not provided'}</span></div>)}</div>{decision&&<div className="notice" role="status">{decision==='approve'?'Approve this flag? The compatibility report and all of its flags will be permanently deleted.':'Deny this flag? This flag will be permanently deleted, and the compatibility report will stay visible.'}</div>}{error&&<div className="notice error" role="alert">{error}</div>}{!decision&&<div className="flag-decision-help"><p><strong>Approve report:</strong> Agree with the flag and permanently delete the compatibility report and all flags on it.</p><p><strong>Deny flag report:</strong> Dismiss and permanently delete this flag. The compatibility report and any other flags remain.</p></div>}<div className="actions modal-actions">{decision?<><button type="button" className="btn dark" disabled={busy} onClick={()=>{setDecision(null);setError('')}}>Go back</button><button type="button" className={'btn '+(decision==='approve'?'red':'green')} disabled={busy} onClick={confirm}>{busy?'Working…':decision==='approve'?'Confirm delete report':'Confirm deny flag'}</button></>:<><button type="button" className="btn red" onClick={()=>setDecision('approve')}>Approve report</button><button type="button" className="btn dark" onClick={()=>setDecision('deny')}>Deny flag report</button></>}</div></div></div>}
function Admin({me}){const [section,setSection]=useState('reports'),[p,setP]=useState(1),[message,setMessage]=useState(''),[confirmPath,setConfirmPath]=useState(null),[reviewFlag,setReviewFlag]=useState(null),[actionBusy,setActionBusy]=useState(false),[gameInput,setGameInput]=useState(''),[emulatorInput,setEmulatorInput]=useState(''),[historyGame,setHistoryGame]=useState(''),[historyEmulator,setHistoryEmulator]=useState(''),[historySort,setHistorySort]=useState('newest');const params=new URLSearchParams({page:String(p)});if(section==='history'){params.set('game',historyGame);params.set('emulator',historyEmulator);params.set('sort',historySort)}const data=useLoad('/admin/'+section+'?'+params);function action(path){setMessage('');setConfirmPath(path)}async function confirmAction(){if(actionBusy||!confirmPath)return;setActionBusy(true);setMessage('');try{await send(confirmPath,'POST',{});setConfirmPath(null);data.reload()}catch(e){setMessage(e.message||'The action failed. Please try again.')}finally{setActionBusy(false)}}if(!me?.is_admin)return <div className="panel empty"><h2>ADMINISTRATOR ACCESS REQUIRED</h2><p>Sign in with the configured administrator account.</p></div>;return <><div className="catalog-head"><div><span className="section-label">LIBRARY MANAGEMENT</span><h1>ADMIN DASHBOARD.</h1><p>Review reports and keep the community library useful.</p></div></div>{reviewFlag&&<FlagReviewDialog flag={reviewFlag} onClose={()=>setReviewFlag(null)} onDone={()=>{setReviewFlag(null);data.reload()}}/>}{confirmPath&&<ModerationDialog path={confirmPath} busy={actionBusy} error={message} onCancel={()=>{setConfirmPath(null);setMessage('')}} onConfirm={confirmAction}/>}<div className="tabs">{['reports','flags','users','history'].map(s=><button className={'btn '+(section===s?'yellow':'dark')} key={s} onClick={()=>{setSection(s);setP(1)}}>{s}</button>)}</div>{message&&!confirmPath&&<div className="notice error" role="alert">{message}</div>}{section==='history'&&<form className="panel history-filter" onSubmit={e=>{e.preventDefault();setP(1);setHistoryGame(gameInput.trim());setHistoryEmulator(emulatorInput.trim())}}><Field label="Game" name="history_game" value={gameInput} onChange={e=>setGameInput(e.target.value)} placeholder="Search game"/><Field label="Emulator" name="history_emulator" value={emulatorInput} onChange={e=>setEmulatorInput(e.target.value)} placeholder="Search emulator"/><label className="field"><span>Sort history</span><select value={historySort} onChange={e=>{setP(1);setHistorySort(e.target.value)}}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="game">Game name</option><option value="emulator">Emulator name</option></select></label><div className="actions history-filter-actions"><button className="btn blue" type="submit">Search</button><button className="btn dark" type="button" onClick={()=>{setGameInput('');setEmulatorInput('');setHistoryGame('');setHistoryEmulator('');setHistorySort('newest');setP(1)}}>Clear</button></div></form>}<div className="panel content-panel"><Notice {...data}>{!data.data?.items.length?<div className="empty">{section==='history'?'No history matches your search.':'Nothing to review here.'}</div>:data.data?.items.map(x=><div className="admin-row" key={x.id}>{section==='reports'?<><strong>{x.game_name} · {x.emulator_name}</strong><p>{x.status} · {x.result} · {x.revision} · {x.os} · {x.cpu} · {x.gpu} · {x.tester} · {String(x.tested_at).slice(0,10)}</p><p>Game version: {x.game_version||'—'} · FPS: {x.fps||'—'}</p><p>Graphics: {x.graphics||'—'}<br/>Settings: {x.settings||'—'}<br/>Notes: {x.notes||'—'}</p><div className="actions"><button className="btn green" onClick={()=>action('/admin/report/'+x.id+'/approve')}>Approve</button><button className="btn red" onClick={()=>action('/admin/report/'+x.id+'/reject')}>Deny</button>{(me.is_admin||String(me.id)===String(x.user_id))&&<><Button to={'/report/edit/'+x.id} variant="dark">Edit</Button><button className="btn dark" onClick={()=>action('/admin/report/'+x.id+'/delete')}>Delete</button></>}</div></>:section==='flags'?<><strong>{x.game_name} · {x.emulator_name}</strong><p>Tester: {x.tester} · Result: {x.result} · Revision: {x.revision} · {x.os}</p><p>Flagged by {x.reporter} · Reason: {x.reason}</p><div className="actions"><button className="btn orange" onClick={()=>setReviewFlag(x)}>View report</button></div></>:section==='users'?<><strong>{x.display_name}</strong><p>Discord ID: {x.discord_id} · {x.role_status}</p><div className="actions">{['active','suspended','banned'].map(s=><button key={s} className="btn dark" onClick={()=>action('/admin/user/'+x.id+'/'+s)}>{s}</button>)}</div></>:<HistoryItem item={x}/>}</div>)}<Pagination page={p} setPage={setP} more={data.data?.hasMore}/></Notice></div><div className="panel content-panel"><h3>MANAGE CATALOG ENTRIES</h3><p>Find an entry in the catalog to edit its metadata. Deleting an entry also deletes its associated reports.</p><div className="actions"><Button to="/games" variant="dark">Browse games</Button><Button to="/emulators" variant="dark">Browse emulators</Button></div></div></>}
function Contribute(){return <div className="form-wrap"><span className="section-label">BUILT TOGETHER</span><h1>HELP THE LIBRARY GROW.</h1><div className="panel content-panel"><h3>HOW COMMUNITY TESTING WORKS</h3><p>Find a game, select an emulator, and tell us what happened during your test. Include your emulator revision, operating system, CPU, GPU, and result. Optional notes help others reproduce your experience.</p><p>Reports appear publicly immediately and can be reviewed by an administrator. You can edit your reports from your account; edited reports return to the review queue.</p></div><div className="panel content-panel"><h3>ADD TO THE CATALOG</h3><p>Sign in with Discord to add a missing game or emulator. Review metadata and artwork before publishing, and include source and license details for images. Avoid duplicates and only use information you can verify.</p><div className="actions"><Button to="/submit/game" variant="yellow">Add a game</Button><Button to="/submit/emulator" variant="blue">Add an emulator</Button></div></div><div className="panel content-panel"><h3>BE A GOOD COMMUNITY MEMBER</h3><p>Submit honest, reproducible results. Flag inaccurate or inappropriate reports for moderator review. This library does not provide game downloads or ROMs.</p></div></div>}
createRoot(document.getElementById('root')).render(<React.StrictMode><DialogProvider><App/></DialogProvider></React.StrictMode>);
